using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class RebirthCamperDrivenPhysicsAudit{
const string Prefab="Assets/REBIRTHPickupRearCornerCandidate_20261021_v1/rebirthCamper80s.prefab";
const string Output="E:/_Haven/shared/REBIRTHStaged/CamperCorrections_20261021/DrivenPhysicsProxyAudit";
static StringBuilder log=new StringBuilder();
static string PathOf(Transform t,Transform root){string p=t.name;while(t.parent&&t.parent!=root){t=t.parent;p=t.name+"/"+p;}return p;}
static void Mode(GameObject root){foreach(var t in root.GetComponentsInChildren<Transform>(true)){if(t.name.StartsWith("REBIRTHMod")||t.name.StartsWith("REBIRTHCamperTurretSlot"))t.gameObject.SetActive(true);if(new[]{"REBIRTHCampRoofStations","REBIRTHCampInteriorStations","REBIRTHCampPowerEquipment","REBIRTHCampStairVisuals","REBIRTHCampWalkInColliders"}.Contains(t.name))t.gameObject.SetActive(false);if(t.name=="REBIRTHCamperBodyModule")t.gameObject.SetActive(true);if(t.name=="REBIRTHPickupOnlyPaint"||t.name=="REBIRTHPickupOnlyBodywork")t.gameObject.SetActive(false);if(t.name.StartsWith("REBIRTHInteraction_")){foreach(var c in t.GetComponents<Collider>())c.enabled=false;}if(t.name=="REBIRTHRearDoorPivot"){foreach(var c in t.GetComponents<Collider>())c.enabled=false;}}}
static void RunCase(int policy,bool drive){var root=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Prefab));root.transform.position=Vector3.up*.5f;Mode(root);var rb=root.GetComponentInChildren<Rigidbody>();var model=root.transform.Find("GameObject");var bodyModule=root.GetComponentsInChildren<Transform>(true).First(t=>t.name=="REBIRTHCamperBodyModule");var hull=root.GetComponentsInChildren<Transform>(true).First(t=>t.name=="CamperHull");hull.SetParent(rb.transform,true);hull.gameObject.SetActive(true);hull.GetComponent<Collider>().enabled=true;// Include enabled native ModelTransform layer14 proxy: no unverified exclusion.
foreach(var t in rb.GetComponentsInChildren<Transform>(true))t.gameObject.layer=21; // Native SetVehicleDriven.
var ground=GameObject.CreatePrimitive(PrimitiveType.Cube);ground.transform.position=new Vector3(0,-.5f,0);ground.transform.localScale=new Vector3(500,1,500);var groundCollider=ground.GetComponent<Collider>();rb.isKinematic=false;rb.useGravity=false;rb.centerOfMass=new Vector3(0,.1f,0);var all=root.GetComponentsInChildren<Collider>(true).Where(c=>!c.isTrigger).ToArray();var owned=all.Where(c=>c.attachedRigidbody==null).ToArray();var compound=all.Where(c=>c.attachedRigidbody==rb).ToArray();var wheels=root.GetComponentsInChildren<WheelCollider>(true);log.AppendLine("CASE policy="+policy+" drive="+drive+" detached="+owned.Length+" compound="+compound.Length);
foreach(var c in owned.Where(c=>c.enabled&&c.gameObject.activeInHierarchy))log.AppendLine("DETACHED "+PathOf(c.transform,root.transform)+" layer="+c.gameObject.layer+" type="+c.GetType().Name+" min="+c.bounds.min.ToString("F4")+" max="+c.bounds.max.ToString("F4"));
Physics.SyncTransforms();foreach(var a in compound.Where(c=>c.enabled&&c.gameObject.activeInHierarchy&&!(c is WheelCollider)))foreach(var b in owned.Where(c=>c.enabled&&c.gameObject.activeInHierarchy))if(Physics.ComputePenetration(a,a.transform.position,a.transform.rotation,b,b.transform.position,b.transform.rotation,out var dir,out float depth))log.AppendLine("OVERLAP "+PathOf(a.transform,root.transform)+" VS "+PathOf(b.transform,root.transform)+" depth="+depth+" direction="+dir.ToString("F4"));
float peakY=rb.position.y,peakSpeed=0,peakSpin=0,maxGroundSelf=0;Vector3 start=rb.position;
for(int step=0;step<650;step++){
// Existing policy only protects detached body subtree; proposed policy includes every owned detached solid.
foreach(var a in compound.Where(c=>c.enabled&&c.gameObject.activeInHierarchy))foreach(var b in owned.Where(c=>c.enabled&&c.gameObject.activeInHierarchy&&(policy==1||c.transform.IsChildOf(bodyModule))))if(!Physics.GetIgnoreCollision(a,b))Physics.IgnoreCollision(a,b,true);
float t=step*.02f;foreach(var w in wheels){w.brakeTorque=t<1?6000:0;w.motorTorque=drive&&t>=1&&rb.velocity.magnitude<10?875:0;w.steerAngle=drive&&w.transform.localPosition.z>0&&t>3&&t<9?Mathf.Sin((t-3)*.7f)*15:0;}
rb.AddForce(Vector3.down*rb.mass*9.81f);Physics.Simulate(.02f);
// Native PhysicsFixedUpdate copies authoritative pose to ModelTransform each tick.
model.SetPositionAndRotation(rb.position,rb.rotation);Physics.SyncTransforms();
int self=0;foreach(var w in wheels)if(w.GetGroundHit(out var hit)&&hit.collider!=null&&hit.collider!=groundCollider)self++;maxGroundSelf=Mathf.Max(maxGroundSelf,self);
peakY=Mathf.Max(peakY,rb.position.y);peakSpeed=Mathf.Max(peakSpeed,rb.velocity.magnitude);peakSpin=Mathf.Max(peakSpin,rb.angularVelocity.magnitude);
if(step%50==49)log.AppendLine("TRACE t="+(t+.02f)+" position="+rb.position.ToString("F4")+" speed="+rb.velocity.magnitude+" spin="+rb.angularVelocity.magnitude+" upright="+rb.transform.up.y+" selfWheelContacts="+self);
}
log.AppendLine("RESULT policy="+policy+" drive="+drive+" peakY="+peakY+" peakSpeed="+peakSpeed+" peakSpin="+peakSpin+" maxSelfWheelContacts="+maxGroundSelf+" final="+rb.position.ToString("F4")+" delta="+(rb.position-start).ToString("F4"));Object.DestroyImmediate(root);Object.DestroyImmediate(ground);}
public static void Run(){Directory.CreateDirectory(Output);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var mode=Physics.simulationMode;Physics.simulationMode=SimulationMode.Script;try{log.AppendLine("Offline Unity DEFAULT PROJECT collisionmatrix14vs21enabled, realwheelgravity, modelpose sync each20ms, body+armor+plow+4turret activation, nativedriverPhysicslayer21. Motor875each=3500total, speedlimit10, rear/frontsame torque, frontsteer±15. Static flatground; no actual game engine,terrain,network or driverCC. policy0existingbody-only ignores;policy1allowneddetachedsolidignores.");foreach(var policy in new[]{0,1})foreach(var drive in new[]{false,true})RunCase(policy,drive);Debug.Log("DRIVEN_PHYSICS_AUDIT_COMPLETE");}finally{Physics.simulationMode=mode;File.WriteAllText(Output+"/driven-audit.txt",log.ToString());}}}
